cat > /tmp/fanin_analyzer.go << 'GOEOF'
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type SymbolKey struct {
	PkgPath    string // import path e.g. github.com/usememos/memos/internal/util
	PkgName    string // local package name
	Name       string // func/method name
	RecvType   string // empty for funcs, type name for methods (without pointer)
	IsMethod   bool
}

type DeclInfo struct {
	Key      SymbolKey
	File     string
	Line     int
	FullName string // display name
}

type CallSite struct {
	File string
	Line int
	Col  int
}

func main() {
	root := "/bench/repo"
	modulePath := "github.com/usememos/memos"

	// Collect all Go files
	var allFiles []string
	fileSet := token.NewFileSet()

	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			base := filepath.Base(path)
			if base == ".git" || base == "vendor" || base == "node_modules" || base == "web" {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") {
			return nil
		}
		// Exclude generated
		base := filepath.Base(path)
		if strings.HasSuffix(base, ".pb.go") || strings.HasSuffix(base, ".pb.gw.go") ||
			strings.Contains(path, "/proto/gen/") {
			return nil
		}
		allFiles = append(allFiles, path)
		return nil
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "walk error: %v\n", err)
		os.Exit(1)
	}

	// Parse all files and build package info
	type fileInfo struct {
		path    string
		astFile *ast.File
		pkgPath string // derived from module + relative dir
		pkgName string
		isInternal bool
	}

	var files []fileInfo
	pkgPathCache := map[string]string{} // dir -> import path

	for _, path := range allFiles {
		f, err := parser.ParseFile(fileSet, path, nil, parser.ParseComments)
		if err != nil {
			fmt.Fprintf(os.Stderr, "parse error %s: %v\n", path, err)
			continue
		}
		rel, _ := filepath.Rel(root, path)
		dir := filepath.Dir(rel)
		pkgPath := modulePath
		if dir != "." {
			pkgPath = modulePath + "/" + filepath.ToSlash(dir)
		}
		pkgPathCache[dir] = pkgPath
		isInternal := strings.HasPrefix(rel, "internal"+string(filepath.Separator)) || strings.HasPrefix(rel, "internal/")
		files = append(files, fileInfo{path, f, pkgPath, f.Name.Name, isInternal})
	}

	// Build declarations in internal/
	decls := map[SymbolKey]DeclInfo{}
	// Also map local name within same package for unqualified calls
	pkgDecls := map[string]map[string][]SymbolKey{} // pkgPath -> name -> keys

	for _, fi := range files {
		if !fi.isInternal {
			continue
		}
		ast.Inspect(fi.astFile, func(n ast.Node) bool {
			switch d := n.(type) {
			case *ast.FuncDecl:
				if d.Name == nil || !d.Name.IsExported() && !isTracked(d.Name.Name) {
					// Track both exported and likely-high-fan-in unexported
				}
				key := SymbolKey{PkgPath: fi.pkgPath, PkgName: fi.pkgName, Name: d.Name.Name}
				pos := fileSet.Position(d.Pos())
				if d.Recv != nil && len(d.Recv.List) > 0 {
					key.IsMethod = true
					key.RecvType = typeName(d.Recv.List[0].Type)
				}
				di := DeclInfo{
					Key:      key,
					File:     fi.path,
					Line:     pos.Line,
					FullName: formatSymbol(key),
				}
				decls[key] = di
				if pkgDecls[fi.pkgPath] == nil {
					pkgDecls[fi.pkgPath] = map[string][]SymbolKey{}
				}
				pkgDecls[fi.pkgPath][d.Name.Name] = append(pkgDecls[fi.pkgPath][d.Name.Name], key)
			}
			return true
		})
	}

	// Track all names (including unexported) for internal
	// Re-scan with all funcs
	decls = map[SymbolKey]DeclInfo{}
	pkgDecls = map[string]map[string][]SymbolKey{}
	declPositions := map[SymbolKey]token.Pos{}

	for _, fi := range files {
		if !fi.isInternal {
			continue
		}
		ast.Inspect(fi.astFile, func(n ast.Node) bool {
			if d, ok := n.(*ast.FuncDecl); ok {
				key := SymbolKey{PkgPath: fi.pkgPath, PkgName: fi.pkgName, Name: d.Name.Name}
				if d.Recv != nil && len(d.Recv.List) > 0 {
					key.IsMethod = true
					key.RecvType = typeName(d.Recv.List[0].Type)
				}
				di := DeclInfo{Key: key, File: fi.path, Line: fileSet.Position(d.Pos()).Line, FullName: formatSymbol(key)}
				decls[key] = di
				declPositions[key] = d.Pos()
				if pkgDecls[fi.pkgPath] == nil {
					pkgDecls[fi.pkgPath] = map[string][]SymbolKey{}
				}
				pkgDecls[fi.pkgPath][d.Name.Name] = append(pkgDecls[fi.pkgPath][d.Name.Name], key)
			}
			return true
		})
	}

	// Count call sites
	callSites := map[SymbolKey][]CallSite{}

	for _, fi := range files {
		// Build import map for this file: localName -> importPath
		imports := map[string]string{}
		for _, imp := range fi.astFile.Imports {
			path := strings.Trim(imp.Path.Value, `"`)
			localName := path
			if imp.Name != nil {
				localName = imp.Name.Name
			} else {
				// default: last component of path
				parts := strings.Split(path, "/")
				localName = parts[len(parts)-1]
			}
			imports[localName] = path
		}
		// Also handle dot imports and self-package
		currentPkg := fi.pkgPath

		ast.Inspect(fi.astFile, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			pos := fileSet.Position(call.Pos())
			var matched []SymbolKey

			switch fun := call.Fun.(type) {
			case *ast.Ident:
				name := fun.Name
				// Same package call
				if keys, ok := pkgDecls[currentPkg][name]; ok {
					for _, k := range keys {
						if !k.IsMethod {
							matched = append(matched, k)
						}
					}
				}
			case *ast.SelectorExpr:
				sel := fun.Sel.Name
				switch x := fun.X.(type) {
				case *ast.Ident:
					// pkg.Func or recv.Method (if recv is var)
					if impPath, ok := imports[x.Name]; ok {
						// Qualified package call: import.Func
						if keys, ok := pkgDecls[impPath][sel]; ok {
							for _, k := range keys {
								if !k.IsMethod {
									matched = append(matched, k)
								}
							}
						}
					} else {
						// Could be method call on local var - harder without types
						// Try matching methods by name in current package only if single candidate
						if keys, ok := pkgDecls[currentPkg][sel]; ok {
							methodKeys := filterMethods(keys)
							if len(methodKeys) == 1 {
								matched = append(matched, methodKeys[0])
							} else if len(methodKeys) > 1 {
								// ambiguous - skip or note
							}
						}
					}
				case *ast.CallExpr, *ast.IndexExpr, *ast.IndexListExpr:
					// chained call result - method call, skip without types
				case *ast.ParenExpr, *ast.StarExpr:
					// (*p).Method or (expr).Method - skip without types
				default:
					// expr.Method - need type info
				}
			}

			for _, k := range matched {
				// Exclude declaration site (the call is inside the func body, not at decl)
				// Declaration itself isn't a CallExpr to itself typically
				cs := CallSite{File: fi.path, Line: pos.Line, Col: pos.Column}
				callSites[k] = append(callSites[k], cs)
			}
			return true
		})
	}

	// Deduplicate call sites by file:line:col
	type result struct {
		Decl  DeclInfo
		Count int
		Sites []CallSite
	}
	var results []result
	for k, di := range decls {
		sites := callSites[k]
		seen := map[string]bool{}
		var unique []CallSite
		for _, s := range sites {
			key := fmt.Sprintf("%s:%d:%d", s.File, s.Line, s.Col)
			if !seen[key] {
				seen[key] = true
				unique = append(unique, s)
			}
		}
		results = append(results, result{di, len(unique), unique})
	}
	sort.Slice(results, func(i, j int) bool {
		if results[i].Count != results[j].Count {
			return results[i].Count > results[j].Count
		}
		return results[i].Decl.FullName < results[j].Decl.FullName
	})

	fmt.Println("=== TOP 30 BY CALL SITE COUNT (AST-only, may miss typed method calls) ===")
	for i, r := range results {
		if i >= 30 {
			break
		}
		if r.Count == 0 {
			break
		}
		rel, _ := filepath.Rel(root, r.Decl.File)
		fmt.Printf("%4d  %s  (%s:%d)\n", r.Count, r.Decl.FullName, rel, r.Decl.Line)
	}
	fmt.Printf("\nTotal internal declarations: %d\n", len(decls))
	fmt.Printf("Total with >=1 call site: %d\n", countNonZero(results))
}

func countNonZero(r []struct {
	Decl  DeclInfo
	Count int
	Sites []CallSite
}) int {
	n := 0
	for _, x := range r {
		if x.Count > 0 {
			n++
		}
	}
	return n
}

func isTracked(name string) bool { return true }

func typeName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.StarExpr:
		return typeName(t.X)
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		return t.Sel.Name
	default:
		return ""
	}
}

func formatSymbol(k SymbolKey) string {
	if k.IsMethod {
		return k.PkgPath + "." + k.RecvType + "." + k.Name
	}
	return k.PkgPath + "." + k.Name
}

func filterMethods(keys []SymbolKey) []SymbolKey {
	var m []SymbolKey
	for _, k := range keys {
		if k.IsMethod {
			m = append(m, k)
		}
	}
	return m
}
