package main

import (
	"fmt"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

const modulePath = "github.com/usememos/memos"

type symbolKey struct {
	PkgPath  string
	Name     string
	RecvType string // empty for funcs; base type name for methods
}

type declInfo struct {
	Key      symbolKey
	File     string
	Line     int
	FullName string
}

type callSite struct {
	File string
	Line int
	Col  int
}

func main() {
	root := "/bench/repo"
	if len(os.Args) > 1 {
		root = os.Args[1]
	}

	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
			packages.NeedImports | packages.NeedTypes | packages.NeedTypesInfo |
			packages.NeedSyntax | packages.NeedModule | packages.NeedDeps,
		Dir:  root,
		Tests: true,
	}

	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load error: %v\n", err)
		os.Exit(1)
	}
	_ = packages.PrintErrors(pkgs)

	decls := map[symbolKey]declInfo{}
	declPos := map[symbolKey]token.Pos{}

	for _, pkg := range pkgs {
		if pkg.IllTyped || pkg.PkgPath == "" {
			continue
		}
		if !isInternalPkg(pkg.PkgPath) {
			continue
		}
		if isGeneratedPkg(pkg) {
			continue
		}
		scope := pkg.Types.Scope()
		for _, name := range scope.Names() {
			obj := scope.Lookup(name)
			fn, ok := obj.(*types.Func)
			if !ok {
				continue
			}
			pos := fn.Pos()
			file, line := positionOf(pkg, pos)
			if file == "" || isGeneratedFile(file) {
				continue
			}
			key := funcToKey(fn)
			di := declInfo{
				Key:      key,
				File:     file,
				Line:     line,
				FullName: formatKey(key),
			}
			decls[key] = di
			declPos[key] = pos
		}
	}

	callSites := map[symbolKey]map[string]callSite{}

	for _, pkg := range pkgs {
		if pkg.IllTyped || pkg.TypesInfo == nil {
			continue
		}
		if isGeneratedPkg(pkg) {
			continue
		}
		for _, id := range pkg.TypesInfo.Uses {
			fn, ok := id.(*types.Func)
			if !ok {
				continue
			}
			key := funcToKey(fn)
			if !isInternalPkg(key.PkgPath) {
				continue
			}
			if _, isDecl := decls[key]; !isDecl {
				continue
			}
			pos := fn.Pos()
			// Uses map keys are the identifier positions (call sites), not object decl positions
			continue
		}
		// Correct iteration: Uses map is pos -> object
		for pos, used := range pkg.TypesInfo.Uses {
			fn, ok := used.(*types.Func)
			if !ok {
				continue
			}
			key := funcToKey(fn)
			if !isInternalPkg(key.PkgPath) {
				continue
			}
			if _, isDecl := decls[key]; !isDecl {
				continue
			}
			if declPos[key] == pos {
				continue
			}
			p := pkg.Fset.Position(pos)
			if isGeneratedFile(p.Filename) {
				continue
			}
			siteKey := fmt.Sprintf("%s:%d:%d", p.Filename, p.Line, p.Column)
			if callSites[key] == nil {
				callSites[key] = map[string]callSite{}
			}
			callSites[key][siteKey] = callSite{File: p.Filename, Line: p.Line, Col: p.Column}
		}
	}

	type result struct {
		Decl  declInfo
		Count int
	}
	var results []result
	for k, di := range decls {
		results = append(results, result{di, len(callSites[k])})
	}
	sort.Slice(results, func(i, j int) bool {
		if results[i].Count != results[j].Count {
			return results[i].Count > results[j].Count
		}
		return results[i].Decl.FullName < results[j].Decl.FullName
	})

	fmt.Println("METHODOLOGY: go/types via golang.org/x/tools/go/packages")
	fmt.Println("- Scope: all packages under module (./...), including _test packages")
	fmt.Println("- Target: func/method objects whose declaring package path contains /internal/")
	fmt.Println("- Count: distinct static identifier-use sites (file:line:column) referencing each symbol")
	fmt.Println("- Excludes: *.pb.go, proto/gen/, vendor/, web/ (non-Go)")
	fmt.Println("- Resolves: imports, receivers, qualified/unqualified names via type checker")
	fmt.Println()

	fmt.Println("=== TOP 40 INTERNAL SYMBOLS BY FAN-IN (distinct call sites) ===")
	shown := 0
	for _, r := range results {
		if r.Count == 0 {
			break
		}
		rel, _ := filepath.Rel(root, r.Decl.File)
		fmt.Printf("%5d  %s  @ %s:%d\n", r.Count, r.Decl.FullName, rel, r.Decl.Line)
		shown++
		if shown >= 40 {
			break
		}
	}

	withCalls := 0
	for _, r := range results {
		if r.Count > 0 {
			withCalls++
		}
	}
	fmt.Printf("\nTotal internal func/method declarations: %d\n", len(decls))
	fmt.Printf("Total with >=1 resolved call site: %d\n", withCalls)

	if len(results) > 0 && results[0].Count > 0 {
		w := results[0]
		rel, _ := filepath.Rel(root, w.Decl.File)
		fmt.Printf("\nWINNER: %s\n", w.Decl.FullName)
		fmt.Printf("DEFINITION: %s:%d\n", rel, w.Decl.Line)
		fmt.Printf("CALL_SITES: %d\n", w.Count)
	}
}

func isInternalPkg(path string) bool {
	return strings.HasPrefix(path, modulePath+"/internal/") || path == modulePath+"/internal"
}

func isGeneratedFile(path string) bool {
	base := filepath.Base(path)
	if strings.HasSuffix(base, ".pb.go") || strings.HasSuffix(base, ".pb.gw.go") {
		return true
	}
	if strings.Contains(path, "/proto/gen/") {
		return true
	}
	return false
}

func isGeneratedPkg(pkg *packages.Package) bool {
	if len(pkg.CompiledGoFiles) == 0 {
		return false
	}
	allGen := true
	for _, f := range pkg.CompiledGoFiles {
		if !isGeneratedFile(f) {
			allGen = false
			break
		}
	}
	return allGen
}

func funcToKey(fn *types.Func) symbolKey {
	key := symbolKey{
		PkgPath: fn.Pkg().Path(),
		Name:    fn.Name(),
	}
	if recv := fn.Type().(*types.Signature).Recv(); recv != nil {
		key.RecvType = baseTypeName(recv.Type())
	}
	return key
}

func baseTypeName(t types.Type) string {
	switch tt := t.(type) {
	case *types.Pointer:
		return baseTypeName(tt.Elem())
	case *types.Named:
		return tt.Obj().Name()
	default:
		return t.String()
	}
}

func positionOf(pkg *packages.Package, pos token.Pos) (file string, line int) {
	if pos == token.NoPos {
		return "", 0
	}
	p := pkg.Fset.Position(pos)
	return p.Filename, p.Line
}

func formatKey(k symbolKey) string {
	if k.RecvType != "" {
		return k.PkgPath + ".(" + k.RecvType + ")." + k.Name
	}
	return k.PkgPath + "." + k.Name
}

