package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

const modulePath = "github.com/usememos/memos"

type symbolKey struct {
	PkgPath  string
	Name     string
	RecvType string
}

type declInfo struct {
	Key      symbolKey
	File     string
	Line     int
	FullName string
}

func main() {
	root := "/bench/repo"
	if len(os.Args) > 1 {
		root = os.Args[1]
	}

	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
			packages.NeedImports | packages.NeedTypes | packages.NeedTypesInfo |
			packages.NeedSyntax | packages.NeedModule | packages.NeedDeps,
		Dir:   root,
		Tests: true,
	}

	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load error: %v\n", err)
		os.Exit(1)
	}
	errCount := packages.PrintErrors(pkgs)
	if errCount > 0 {
		fmt.Fprintf(os.Stderr, "(%d package errors, continuing)\n", errCount)
	}

	decls := map[symbolKey]declInfo{}

	for _, pkg := range pkgs {
		if pkg.IllTyped || pkg.PkgPath == "" || isGeneratedPkg(pkg) {
			continue
		}
		if !isInternalPkg(pkg.PkgPath) {
			continue
		}
		for _, name := range pkg.Types.Scope().Names() {
			fn, ok := pkg.Types.Scope().Lookup(name).(*types.Func)
			if !ok {
				continue
			}
			pos := fn.Pos()
			file, line := positionOf(pkg, pos)
			if file == "" || isGeneratedFile(file) {
				continue
			}
			key := funcToKey(fn)
			decls[key] = declInfo{Key: key, File: file, Line: line, FullName: formatKey(key)}
		}
	}

	callSites := map[symbolKey]map[string]struct{}{}

	for _, pkg := range pkgs {
		if pkg.IllTyped || pkg.TypesInfo == nil || isGeneratedPkg(pkg) {
			continue
		}
		for _, file := range pkg.Syntax {
			filePath := pkg.Fset.Position(file.FileStart).Filename
			if isGeneratedFile(filePath) {
				continue
			}
			ast.Inspect(file, func(n ast.Node) bool {
				call, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}
				var fnObj types.Object
				switch fun := call.Fun.(type) {
				case *ast.Ident:
					fnObj = pkg.TypesInfo.Uses[fun]
				case *ast.SelectorExpr:
					fnObj = pkg.TypesInfo.Uses[fun.Sel]
				default:
					return true
				}
				fn, ok := fnObj.(*types.Func)
				if !ok {
					return true
				}
				key := funcToKey(fn)
				if !isInternalPkg(key.PkgPath) {
					return true
				}
				if _, isDecl := decls[key]; !isDecl {
					return true
				}
				p := pkg.Fset.Position(call.Lparen)
				if p.Filename == "" {
					p = pkg.Fset.Position(call.Pos())
				}
				if isGeneratedFile(p.Filename) {
					return true
				}
				siteKey := fmt.Sprintf("%s:%d:%d", p.Filename, p.Line, p.Column)
				if callSites[key] == nil {
					callSites[key] = map[string]struct{}{}
				}
				callSites[key][siteKey] = struct{}{}
				return true
			})
		}
	}

	type result struct {
		Decl  declInfo
		Count int
	}
	var results []result
	for k, di := range decls {
		results = append(results, result{di, len(callSites[k])})
	}
	sort.Slice(results, func(i, j int) bool {
		if results[i].Count != results[j].Count {
			return results[i].Count > results[j].Count
		}
		return results[i].Decl.FullName < results[j].Decl.FullName
	})

	fmt.Println("METHODOLOGY: go/types + ast.CallExpr via golang.org/x/tools/go/packages")
	fmt.Println("- Scope: all ./... packages including tests (_test packages)")
	fmt.Println("- Target: *types.Func declared in github.com/usememos/memos/internal/...")
	fmt.Println("- Count: distinct static CallExpr sites (file:line:column at '(' of call)")
	fmt.Println("- Excludes: *.pb.go, proto/gen/, vendor/; declaration sites; non-call references")
	fmt.Println("- Resolves: imports, receivers, embedding, interface calls via type checker")
	fmt.Println()

	fmt.Println("=== TOP 40 INTERNAL SYMBOLS BY FAN-IN ===")
	for i, r := range results {
		if r.Count == 0 || i >= 40 {
			break
		}
		rel, _ := filepath.Rel(root, r.Decl.File)
		fmt.Printf("%5d  %s  @ %s:%d\n", r.Count, r.Decl.FullName, rel, r.Decl.Line)
	}

	withCalls := 0
	for _, r := range results {
		if r.Count > 0 {
			withCalls++
		}
	}
	fmt.Printf("\nTotal internal func/method declarations: %d\n", len(decls))
	fmt.Printf("Total with >=1 call site: %d\n", withCalls)

	if len(results) > 0 && results[0].Count > 0 {
		w := results[0]
		rel, _ := filepath.Rel(root, w.Decl.File)
		fmt.Printf("\nWINNER: %s\n", w.Decl.FullName)
		fmt.Printf("DEFINITION: %s:%d\n", rel, w.Decl.Line)
		fmt.Printf("CALL_SITES: %d\n", w.Count)
	}

	// Also run variant counting Uses (all references) for top 5 comparison
	fmt.Println("\n=== TOP 10 BY ALL USES (not just calls, for comparison) ===")
	useSites := countAllUses(pkgs, decls)
	var useResults []result
	for k, di := range decls {
		useResults = append(useResults, result{di, len(useSites[k])})
	}
	sort.Slice(useResults, func(i, j int) bool {
		if useResults[i].Count != useResults[j].Count {
			return useResults[i].Count > useResults[j].Count
		}
		return useResults[i].Decl.FullName < useResults[j].Decl.FullName
	})
	for i, r := range useResults {
		if r.Count == 0 || i >= 10 {
			break
		}
		fmt.Printf("%5d  %s\n", r.Count, r.Decl.FullName)
	}
}

func countAllUses(pkgs []*packages.Package, decls map[symbolKey]declInfo) map[symbolKey]map[string]struct{} {
	sites := map[symbolKey]map[string]struct{}{}
	for _, pkg := range pkgs {
		if pkg.IllTyped || pkg.TypesInfo == nil || isGeneratedPkg(pkg) {
			continue
		}
		for id, used := range pkg.TypesInfo.Uses {
			fn, ok := used.(*types.Func)
			if !ok {
				continue
			}
			key := funcToKey(fn)
			if !isInternalPkg(key.PkgPath) {
				continue
			}
			if _, isDecl := decls[key]; !isDecl {
				continue
			}
			p := pkg.Fset.Position(id.Pos())
			if isGeneratedFile(p.Filename) {
				continue
			}
			sk := fmt.Sprintf("%s:%d:%d", p.Filename, p.Line, p.Column)
			if sites[key] == nil {
				sites[key] = map[string]struct{}{}
			}
			sites[key][sk] = struct{}{}
		}
	}
	return sites
}

func isInternalPkg(path string) bool {
	return strings.HasPrefix(path, modulePath+"/internal/")
}

func isGeneratedFile(path string) bool {
	base := filepath.Base(path)
	if strings.HasSuffix(base, ".pb.go") || strings.HasSuffix(base, ".pb.gw.go") {
		return true
	}
	return strings.Contains(path, "/proto/gen/")
}

func isGeneratedPkg(pkg *packages.Package) bool {
	if len(pkg.CompiledGoFiles) == 0 {
		return false
	}
	for _, f := range pkg.CompiledGoFiles {
		if !isGeneratedFile(f) {
			return false
		}
	}
	return true
}

func funcToKey(fn *types.Func) symbolKey {
	pkgPath := ""
	if fn.Pkg() != nil {
		pkgPath = fn.Pkg().Path()
	}
	key := symbolKey{PkgPath: pkgPath, Name: fn.Name()}
	if recv := fn.Type().(*types.Signature).Recv(); recv != nil {
		key.RecvType = baseTypeName(recv.Type())
	}
	return key
}

func baseTypeName(t types.Type) string {
	switch tt := t.(type) {
	case *types.Pointer:
		return baseTypeName(tt.Elem())
	case *types.Named:
		return tt.Obj().Name()
	default:
		return t.String()
	}
}

func positionOf(pkg *packages.Package, pos token.Pos) (file string, line int) {
	if pos == token.NoPos {
		return "", 0
	}
	p := pkg.Fset.Position(pos)
	return p.Filename, p.Line
}

func formatKey(k symbolKey) string {
	if k.RecvType != "" {
		return k.PkgPath + ".(" + k.RecvType + ")." + k.Name
	}
	return k.PkgPath + "." + k.Name
}

