				continue
			}
			var curFunc string
			ast.Inspect(file, func(n ast.Node) bool {
				if fd, ok := n.(*ast.FuncDecl); ok {
					name := fd.Name.Name
					if fd.Recv != nil && len(fd.Recv.List) > 0 {
						name = recvName(fd.Recv.List[0].Type) + "." + name
					}
					curFunc = pkg.PkgPath + "::" + name
				}
				call, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}
				sel, ok := call.Fun.(*ast.SelectorExpr)
				if !ok {
					return true
				}
				fn, ok := pkg.TypesInfo.Uses[sel.Sel].(*types.Func)
				if !ok || fn.Name() != "CompileToStatement" {
					return true
				}
				if fn.Pkg() == nil || fn.Pkg().Path() != modulePath+"/internal/filter" {
					return true
				}
				p := pkg.Fset.Position(call.Lparen)
				sk := fmt.Sprintf("%s:%d:%d", p.Filename, p.Line, p.Column)
				callers[curFunc+" -> "+sk] = true
				sites++
				return true
			})
		}
	}
	// distinct caller functions
	funcSet := map[string]bool{}
	for k := range callers {
		parts := strings.Split(k, " -> ")
		funcSet[parts[0]] = true
	}
	var flist []string
	for f := range funcSet {
		flist = append(flist, f)
	}
	sort.Strings(flist)
	fmt.Printf("Distinct caller functions (enclosing func): %d\n", len(flist))
	for _, f := range flist {
		fmt.Printf("  %s\n", f)
	}
}

func recvName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.StarExpr:
		return recvName(t.X)
	case *ast.Ident:
		return t.Name
	default:
		return "?"
	}
}
